-- Phase 13B-C — canonical access registry (version 1).
--
-- Source of truth: app/lib/access/registry.ts. The seed block below is generated by
-- app/lib/access/registrySql.ts and parity-tested (app/lib/access/registrySql.test.ts);
-- the migration fails if the seeded registry violates any invariant enforced by
-- private.assert_access_registry_valid_v1 (mirrors validateAccessRegistry()).
--
-- Registry tables are policy metadata, not tenant data: RLS on, no policies, no
-- client grants. Only SECURITY DEFINER evaluator/mutation functions read them.
--
-- Scope kinds (closed set): company | granted_jobs (jobs with an active
-- job_access_grants row for the member) | job (rule-level scope_job_id) | own_task
-- (task assigned to the actor inside an accessible job). branch / sales_team are
-- reserved and always deny.

create table public.access_capabilities (
  capability_key text primary key check (capability_key ~ '^[a-z_]+(\.[a-z_]+)+$'),
  domain text not null,
  status text not null check (status in ('active', 'reserved')),
  sensitive boolean not null,
  scope_kinds text[] not null check (
    cardinality(scope_kinds) >= 1
    and scope_kinds <@ array['company', 'granted_jobs', 'job', 'own_task']::text[]
  ),
  registry_version integer not null default 1
);

create table public.access_capability_dependencies (
  capability_key text not null references public.access_capabilities (capability_key),
  requires_capability_key text not null references public.access_capabilities (capability_key),
  primary key (capability_key, requires_capability_key),
  check (capability_key <> requires_capability_key)
);

create table public.access_role_profiles (
  role_key text not null check (role_key in ('owner', 'admin', 'office_sales', 'production_lead', 'field_user')),
  version integer not null check (version >= 1),
  primary key (role_key, version)
);

create table public.access_role_profile_capabilities (
  role_key text not null,
  version integer not null,
  capability_key text not null references public.access_capabilities (capability_key),
  scope_kind text not null check (scope_kind in ('company', 'granted_jobs', 'job', 'own_task')),
  primary key (role_key, version, capability_key),
  foreign key (role_key, version) references public.access_role_profiles (role_key, version)
);

create table public.access_packages (
  package_key text primary key check (package_key ~ '^[a-z_]+$'),
  status text not null check (status in ('active', 'reserved')),
  sensitive boolean not null,
  strong_auth_required boolean not null,
  scope_kind text not null check (scope_kind in ('company', 'granted_jobs')),
  eligible_roles text[] not null check (
    cardinality(eligible_roles) >= 1
    and eligible_roles <@ array['admin', 'office_sales', 'production_lead', 'field_user']::text[]
  ),
  assignable_by text[] not null check (
    cardinality(assignable_by) >= 1
    and assignable_by <@ array['owner', 'admin', 'production_lead']::text[]
    and 'owner' = any (assignable_by)
  )
);

create table public.access_package_capabilities (
  package_key text not null references public.access_packages (package_key),
  capability_key text not null references public.access_capabilities (capability_key),
  primary key (package_key, capability_key)
);

alter table public.access_capabilities enable row level security;
alter table public.access_capability_dependencies enable row level security;
alter table public.access_role_profiles enable row level security;
alter table public.access_role_profile_capabilities enable row level security;
alter table public.access_packages enable row level security;
alter table public.access_package_capabilities enable row level security;

revoke all on table
  public.access_capabilities,
  public.access_capability_dependencies,
  public.access_role_profiles,
  public.access_role_profile_capabilities,
  public.access_packages,
  public.access_package_capabilities
from public, anon, authenticated, service_role;

-- BEGIN GENERATED REGISTRY SEED (app/lib/access/registrySql.ts)
-- END GENERATED REGISTRY SEED


-- Registry invariants (mirror of validateAccessRegistry()). Returns the list of
-- violations; the migration asserts it is empty.
create or replace function private.access_registry_violations_v1()
returns text[]
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  with recursive walk (root, node, path, cycle) as (
    select d.capability_key, d.requires_capability_key,
           array[d.capability_key, d.requires_capability_key], d.capability_key = d.requires_capability_key
    from public.access_capability_dependencies d
    union all
    select w.root, d.requires_capability_key, w.path || d.requires_capability_key,
           d.requires_capability_key = any (w.path)
    from walk w
    join public.access_capability_dependencies d on d.capability_key = w.node
    where not w.cycle
  ),
  violations (v) as (
    select 'dependency cycle: ' || array_to_string(path, ' -> ') from walk where cycle
    union all
    select c.capability_key || ': active capability depends on reserved ' || r.capability_key
    from public.access_capability_dependencies d
    join public.access_capabilities c on c.capability_key = d.capability_key
    join public.access_capabilities r on r.capability_key = d.requires_capability_key
    where c.status = 'active' and r.status <> 'active'
    union all
    select pc.role_key || ': inactive or out-of-scope ' || pc.capability_key
    from public.access_role_profile_capabilities pc
    join public.access_capabilities c on c.capability_key = pc.capability_key
    where c.status <> 'active' or not (pc.scope_kind = any (c.scope_kinds))
    union all
    select 'owner v' || p.version || ': missing ' || c.capability_key
    from public.access_role_profiles p
    cross join public.access_capabilities c
    where p.role_key = 'owner' and c.status = 'active'
      and not exists (
        select 1 from public.access_role_profile_capabilities pc
        where pc.role_key = p.role_key and pc.version = p.version
          and pc.capability_key = c.capability_key and pc.scope_kind = 'company'
      )
    union all
    select pk.package_key || ': active package holds reserved ' || c.capability_key
    from public.access_package_capabilities pk
    join public.access_packages p on p.package_key = pk.package_key
    join public.access_capabilities c on c.capability_key = pk.capability_key
    where p.status = 'active' and c.status <> 'active'
    union all
    select pk.package_key || ': ' || c.capability_key || ' not allowed at ' || p.scope_kind
    from public.access_package_capabilities pk
    join public.access_packages p on p.package_key = pk.package_key
    join public.access_capabilities c on c.capability_key = pk.capability_key
    where not (p.scope_kind = any (c.scope_kinds))
    union all
    select p.package_key || ': ' || er.role_key || ' lacks prerequisite ' || d.requires_capability_key
           || ' for ' || d.capability_key
    from public.access_packages p
    cross join lateral unnest(p.eligible_roles) as er (role_key)
    join public.access_package_capabilities pk on pk.package_key = p.package_key
    join public.access_capability_dependencies d on d.capability_key = pk.capability_key
    where p.status = 'active'
      and not exists (
        select 1 from public.access_package_capabilities x
        where x.package_key = p.package_key and x.capability_key = d.requires_capability_key
      )
      and not exists (
        select 1 from public.access_role_profile_capabilities pc
        where pc.role_key = er.role_key and pc.version = 1
          and pc.capability_key = d.requires_capability_key
          and pc.scope_kind in ('company', p.scope_kind)
      )
  )
  select coalesce(array_agg(v order by v), '{}'::text[]) from violations;
$$;

revoke all on function private.access_registry_violations_v1() from public;
grant execute on function private.access_registry_violations_v1() to service_role;

do $$
declare
  v_violations text[] := private.access_registry_violations_v1();
begin
  if cardinality(v_violations) > 0 then
    raise exception 'access registry invalid: %', array_to_string(v_violations, '; ');
  end if;
end;
$$;
